@Injectable()                       // registered in the module's providers array
export class OrderFacade {
  constructor(
    private readonly pricing: PricingService,
    private readonly inventory: InventoryService,
    private readonly repo: OrderRepository) {}
  async placeOrder(req: PlaceOrderRequest): Promise<OrderId> {   // coarse-grained
    const quote = await this.pricing.quote(req.sku, req.qty);
    await this.inventory.reserve(req.sku, req.qty);
    return this.repo.insert({ customerId: req.customerId, quote });
  }
}

