// services/orders.ts - the module is the facade
import { quote } from "../pricing/pricing.js";
import { reserve } from "../inventory/inventory.js";
import { insertOrder } from "../data/orders.js";
import type { PlaceOrderRequest, OrderId } from "./contracts.js";

export async function placeOrder(req: PlaceOrderRequest): Promise<OrderId> {
  const q = await quote(req.sku, req.qty);           // coarse-grained use case
  await reserve(req.sku, req.qty);
  return insertOrder({ customerId: req.customerId, quote: q });
}
